// MedicationRequest -> DrugPrescriptionEvent
// Does not manage (yet):
// - hasTimePattern   (decoded from timing in later work)
map "http://research.balgrist.ch/fhir2sphn/StructureMap/MedicationRequestToDrugPrescriptionEvent" = "MedicationRequestToDrugPrescriptionEvent"

// Source definitions
uses "http://hl7.org/fhir/StructureDefinition/MedicationRequest" alias MedicationRequest as source
uses "http://hl7.org/fhir/StructureDefinition/Medication" alias Medication as source
uses "http://hl7.org/fhir/StructureDefinition/Meta" alias Meta as source

// Target definitions (SPHN)
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Content" alias Content as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-DrugPrescriptionEvent" alias DrugPrescriptionEvent as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-DrugPrescription" alias DrugPrescription as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Drug" alias Drug as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Substance" alias Substance as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Quantity" alias Quantity as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-Unit" alias Unit as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-PharmaceuticalDoseForm" alias PharmaceuticalDoseForm as target
uses "http://research.balgrist.ch/fhir2sphn/StructureDefinition/SPHN-DrugArticle" alias DrugArticle as target

imports "http://research.balgrist.ch/fhir2sphn/StructureMap/Utils"

group medication_request(source mr : MedicationRequest, target content : Content) <<types>> {
    mr -> content.DrugPrescriptionEvent = create('DrugPrescriptionEvent') as event then {
        mr.meta as m then refSourceSystem(m, event);
        mr.id as id -> event.id = ('MedicationRequest/' & %id);

        // authoredOn -> hasDateTime (ALWAYS; 1..1). Per-administration times go on the DrugPrescription.
        mr.authoredOn as authored -> event.hasDateTime = authored;
        mr.encounter as encounter -> event.hasAdministrativeCase = encounter;

        // One DrugPrescription per dosageInstruction (decision #1). The single contained
        // Medication is shared, but each DrugPrescription gets its OWN Drug so the
        // per-instruction dose/rate can be attached.
        mr.dosageInstruction as di -> event.hasDrugPrescription = create('DrugPrescription') as presc then {
            mr.contained as medication where $this.ofType(FHIR.Medication) -> presc.hasDrug = create('Drug') as drug then {
                // article / ingredient / doseForm from the Medication (shared group)
                mr.meta as m then medication_to_drug(medication, m, drug);

                // dose / rate from THIS dosageInstruction -> Drug.hasQuantity (per planned administration)
                di.doseAndRate as dr then {
                    dr.dose : Quantity as value where $this.system = 'http://unitsofmeasure.org' -> drug.hasQuantity as q then quantity(value, q) "doseQuantity_ucum";
                    // orderable drug form (TAB/CAP/...) -> UCUM {#}
                    dr.dose : Quantity as value where $this.system = 'http://terminology.hl7.org/CodeSystem/v3-orderableDrugForm' -> drug.hasQuantity as quantity then {
                        value.value as v -> quantity.id = uuid(), quantity.hasValue = v, quantity.hasUnit as unit then unit_number(value, unit);
                    } "doseQuantity_orderableDrugForm";
                    // rateQuantity (continuous infusion, pattern H) -> Drug.hasQuantity (rate unit)
                    dr.rate : Quantity as value where $this.system = 'http://unitsofmeasure.org' -> drug.hasQuantity as q then quantity(value, q) "rateQuantity_ucum";
                };
            };

            // route (defensive; absent in sample data) -> hasAdministrationRouteCode
            di.route as route then {
                route.coding first as coding where $this.system = 'http://snomed.info/sct' -> presc.hasAdministrationRouteCode as routeCode then {
                    coding.code as code -> routeCode.termid = code as termid,
                    routeCode.iri = append('http://snomed.info/id/', termid);
                };
            };

            // datetime: the event timestamp (Multiplan) is the start and SUPPRESSES the
            // generic boundsPeriod.start rule, so the 0..1 hasStartDateTime is never doubly set.
            di.timing as tim then {
                tim.event first as ev -> presc.hasStartDateTime = ev "start_from_event";
                tim as t where $this.event.empty() then {
                    t.repeat as r then {
                        r.boundsPeriod as bp then {
                            bp.start as s -> presc.hasStartDateTime = s "start_from_bounds";
                        };
                    };
                } "no_event_start";
                tim.repeat as r2 then {
                    r2.boundsPeriod as bp2 then {
                        bp2.end as e -> presc.hasEndDateTime = e "end_from_bounds";
                    };
                };
            };
        } "DrugPrescription";
    } "DrugPrescriptionEvent";
}

// Shared, parameterised: contained Medication -> Drug (article / ingredient / doseForm).
// Drug.hasQuantity (dose/rate) is set per-dosageInstruction by the caller.
// Mirrors the drug logic of MedicationAdministrationToDrugAdministrationEvent.map.
group medication_to_drug(source medication : Medication, source meta : Meta, target drug : Drug) {
    meta as m then refSourceSystem(m, drug) "src_drug";
    medication.id as id -> drug.id = uuid();

    medication.ingredient as ingredient where $this.isActive = true then {
        ingredient -> drug.hasActiveIngredient = create('Substance') as substance then {
            meta as m then refSourceSystem(m, substance) "src_substance";
            ingredient -> substance.id = uuid() "substance_id";

            // Medication/ingredient/coding -> Drug/hasActiveIngredient/code
            ingredient.item : CodeableConcept as code then {
                code.coding first as coding where $this.system = "http://www.cas.org" -> substance.hasCode as substanceCode then {
                    coding.code as c -> substanceCode.id = uuid(), substanceCode.hasIdentifier = c;
                    coding.system as s -> substanceCode.hasCodingSystemAndVersion = s;
                };
                code.coding first as coding where $this.system = "http://snomed.info/sct" -> substance.hasCode as substanceCode then {
                    coding.code as code -> substanceCode.termid = code as termid,
                    substanceCode.iri = append('http://snomed.info/id/', termid);
                };

                // Medication/ingredient/text -> Drug/hasActiveIngredient/hasGenericName
                code.text as text -> substance.hasGenericName = text;
            };

            // Medication/ingredient/strength/extension/sphn#Substance_hasQuantity -> Substance/hasQuantity
            ingredient.strength as strength then {
                strength.extension first as e where $this.url = "https://www.biomedit.ch/rdf/sphn-schema/sphn#Substance_hasQuantity" then {
                    e.value : Quantity as value -> substance.hasQuantity as q then quantity(value, q);
                } "valueQuantity";
            };
        } "Substance";
    };

    medication.code as code -> drug.hasArticle = create('DrugArticle') as article then {
        meta as m then refSourceSystem(m, article) "src_article";
        code -> article.id = uuid() "article_id";

        // Medication/code/coding -> Drug/hasArticle/hasCode
        code.coding as coding where $this.system = 'https://wwww.gs1.org/standards/id-keys/gtin' -> article.hasCode as articleCode then {
            coding.code as c -> articleCode.id = uuid(), articleCode.hasIdentifier = c;
            coding.system as s -> articleCode.hasCodingSystemAndVersion = s;
        };

        // Medication/code/text -> Drug/hasArticle/hasName
        code.text as text -> article.hasName = text;

        // Medication/form -> Drug/hasArticle/hasManufacturedDoseForm
        medication.form as form then {
            form.coding first as coding -> article.hasManufacturedDoseForm = create('PharmaceuticalDoseForm') as doseForm then {
                coding -> doseForm.id = uuid(),
                doseForm.hasCode as DoseFormCode then {
                    coding.code as c -> DoseFormCode.id = uuid(), DoseFormCode.hasIdentifier = c;
                    coding.system as s ->  DoseFormCode.hasCodingSystemAndVersion = s;
                    coding.display as d -> DoseFormCode.hasName = d;
                } "doseForm_code";
            } "doseForm";
        };
    };
}
